sections=json.loads((OUT/'sections.json').read_text(encoding='utf-8'))
screens=[
('01-login','כניסה למערכת','Workspace/Login.cshtml','WorkspaceController.Login → AuthController.Login','זהו השער למערכת. המשתמש מקליד דוא״ל וסיסמה ולוחץ Sign in. קישור Create an account מוביל להרשמת רוכב. הודעת כשל מוצגת בתוך הטופס, ושדה הסיסמה מוסווה. אין במסך בחירת תפקיד; התפקיד נקבע מהחשבון שנשמר במסד.','ה־View שולחת POST עם token נגד CSRF. ה־Controller מעביר את הנתונים ל־API ומפנה לדשבורד לאחר הצלחה. רוכב מנותב בהמשך לאזור הרוכבים. Get של Login רק מציג את הטופס; Post מבצע אימות. אין להכניס לספר סיסמת מנהל אמיתית.'),
('02-register','הרשמת רוכב','Workspace/Register.cshtml','WorkspaceController.Register → AuthController.Register','הטופס כולל שם, דוא״ל וסיסמה. הודעות validation מופיעות לצד השדות וסיכום שגיאות מופיע בראש הטופס. לחיצה על Create account יוצרת חשבון RIDER בלבד, ולא חשבון צוות. לאחר הרשמה מוצלחת מופיעה הפניה לכניסה.','asp-for מחבר את שדות השם והדוא״ל ל־RegisterRequest. הסיסמה אינה מוחזרת לערך השדה אחרי שגיאה. minlength ו־required עוזרים למשתמש בדפדפן, אך השרת מפעיל DataAnnotations גם אם לקוח עוקף את בדיקות ה־HTML.'),
('03-overview','סקירת מצב הצי','Workspace/Dashboard.cshtml','WorkspaceController.Dashboard → FleetController.Dashboard','הדשבורד מציג כמות זמינה, תחנות בריאות, אזהרות, תחנות קריטיות, התראות ומשימות. למעלה מופיעים זמן יצירת הדף וזמן דיווח המקור. רשימת Priority watchlist מציגה את שש התחנות בסיכון הגבוה ביותר; Recommended moves מציגה הצעות פעולה.','בתצלום המתועד התקבל מצב של נתונים לא עדכניים בכל התחנות. לכן כמות זמינה מוצגת כמקף והתחנות מסומנות באזהרה. זו תמונת המערכת בזמן הצילום, ולא הוכחה שאין אופניים. ה־View מציגה נתוני JSON ו־partials; החישוב עצמו נמצא בשירותים.'),
('04-stations','רשימת תחנות וחיפוש','Workspace/Stations.cshtml','WorkspaceController.Stations → FleetController.Stations','רשימת התחנות מאפשרת חיפוש לפי שם או מזהה וסינון לפי סטטוס. כל שורה מציגה שם, מזהה, זמינות, תפוסה, סיכון, מגמה וזמני דיווח וקבלה. לחיצה על התחנה פותחת פירוט. הבחירה בשמות ראשיים ובמזהים משניים מונעת צורך לזכור UUID.','Stations מקבלת את הרשימה ומסננת אותה לפי query parameters. _StationTable אחראית לרינדור המשותף. אין כאן pagination של השרת; ברשת גדולה כל הנתונים מוחזרים לפני סינון התצוגה. השהיית refresh מאפשרת לעיין בתוצאות בלי החלפת הדף באמצע.'),
('05-station','פרטי תחנה והיסטוריה','Workspace/Station.cshtml','WorkspaceController.Station → FleetController.Station','הדף מרכז את מצב התחנה: זמינות, תפוסה, ציון סיכון וקצב נטו, מצב תפעולי, תחזית וגרף קריאות. מתחת מופיעות המלצות והתראות הקשורות לתחנה. יש להשוות בין זמן המקור לבין זמן הקבלה לפני החלטה על העברה.','ה־View בונה polyline ב־SVG מתוך ההיסטוריה הממוינת. דף זה משתמש בשאילתה ממוקדת למזהה ולא מחשב תחילה את כל התחנות. נתונים ישנים גורמים לתצוגת Unknown או Not predicted. סגירת התראה עשויה לשנות מצב תפעולי בלי לשנות את המדידה החיצונית.'),
('06-alerts','התראות תפעוליות','Workspace/Alerts.cshtml','WorkspaceController.Alerts → OperationsController.Alerts','המסך מציג התראות עם חומרה, סטטוס, תחנה ותיאור. ניתן לסנן לפי חומרה, מצב ותחנה. קישור לפתרון מעביר למסך אישור, ולא שולח כתיבה באמצעות GET. שם התחנה משלים את המזהה הטכני.','פעולת הרשימה נבנית ב־EF כשאילתה עם תנאים אופציונליים ומוגבלת ל־500 רשומות. Resolve שומרת RESOLVED, זמן ומבצע ואז פוסלת מטמון. אם הספק ממשיך לדווח על בעיה, לאחר תקופת ההמתנה עשויה להיווצר התראה חדשה; זו רשומה חדשה ולא ביטול של פעולת המשתמש.'),
('07-rebalancing','משימות העברת אופניים','Workspace/Recommendations.cshtml','WorkspaceController.Recommendations / Apply → OperationsController.Update','כרטיס משימה מציג כמות, מקור, יעד, סיבה, עדיפות וסטטוס. Start task מסמן תחילת טיפול, Mark completed מציין השלמה ו־Dismiss דוחה המלצה. מסנן Task status מאפשר לצפות גם בהיסטוריה של משימות סגורות.','לאחר שינוי מוצלח, Apply מפנה לרשימה עם הסטטוס שהוחזר מהשרת ו־updatedId. הכרטיס מודגש והרשימה ממוינת לפי UpdatedAt. משימה שהושלמה אינה מציגה שוב כפתור השלמה. הנתונים בזמן הצילום עשויים להכיל בעיקר משימות שנדחו בגלל מדידות ישנות.'),
('08-metrics','מדדי השפעה','Workspace/Metrics.cshtml','WorkspaceController.Metrics → MetricsController.Get → MetricsService.Summary','המסך מציג דקות תחנה ריקה, זמן תגובה ממוצע, אחוז השלמה ושגיאת תחזית ל־30 דקות. לכל מדד מוצגת משמעותו או כמות המדגמים. בהמשך יש שינוי בזמינות אחרי עבודה וטבלת זמן ריק לפי תחנה.','חלון המשימות והתחזיות הוא שבעה ימים; חלון קריאות ההיסטוריה נקבע בהגדרות. מקף פירושו שאין מספיק דגימות, לא ביצוע מושלם. Minutes משתמשת ב־DurationText, בעוד MAE נשאר מספר אופניים. צילום המסך אינו ניסוי מבוקר המוכיח השפעה סיבתית.'),
('09-reports','דיווחי רוכבים לצוות','Workspace/Reports.cshtml','WorkspaceController.Reports / ResolveReport → RiderIssuesController','מנהל ועובד יכולים לעיין בדיווחים שהתקבלו מרוכבים, לקרוא את התיאור ולפתור דיווח פתוח. המסך מאפשר להפריד בין מחסור אוטומטי בזמינות לבין בעיה שרוכב תיאר, כגון מתקן שאינו פועל. כאשר אין דיווחים, מוצג מצב ריק.','ResolveReport מבצעת POST לנתיב הפתרון ומחזירה למסך הרשימה. ה־API הוא שקובע הרשאות ושומר את האודיט. תמונה ריקה אינה סיבה להוסיף תקלה פיקטיבית לרשת; לצורכי בדיקה יש לסמן במפורש כל דיווח שנוצר ולסגור אותו לאחר השימוש.'),
('10-users','ניהול משתמשים','Workspace/Users.cshtml','WorkspaceController.Users → UsersController.All','מסך המנהל מרכז שם, דוא״ל, תפקיד ומצב פעילות. ניתן לפתוח יצירה, עריכה או שינוי פעילות. אין להציג PasswordHash בטבלה. עובד ורוכב אינם מקבלים גישה לפעולות ניהול גם אם הם מנסים את הכתובת ישירות.','All משתמשת ב־AsNoTracking וממפה ל־UserView. שינוי מצב משתמש שומר את הרשומה במקום למחוק היסטוריה. קובץ המשתמשים המקורי ונתוני משתמשי התיעוד נשארים במסד; חשבונות התיעוד הושבתו בתום הצילום.'),
('11-add-user','יצירת חבר צוות','Workspace/EditUser.cshtml','WorkspaceController.SaveUser → UsersController.Create','אותה תצוגה משמשת ליצירה ולעריכה. במצב יצירה אין id, הסיסמה נדרשת והמנהל בוחר תפקיד ופעילות. אחרי Save user השרת מאמת פרטים, בודק דוא״ל ייחודי ומגובב את הסיסמה.','המשתנה editing נגזר מהמזהה במודל. הוא קובע כותרת, שדה id והאם סיסמה היא חובה. הטופס אינו שולח בקשה להקמת חשבון במערכת חיצונית; הוא יוצר משתמש מקומי בפרויקט. בבדיקות התיעוד נוצרו חשבונות לדוגמה באישור המגישים.'),
('12-profile','פרופיל משתמש','Workspace/Profile.cshtml','WorkspaceController.Profile → AuthController.Me','הפרופיל מציג את זהות החשבון המחובר, תפקידו ופרטי החשבון הזמינים ב־UserView. תפקידו לאפשר למשתמש להבין באיזו זהות הוא עובד, בעיקר כאשר מדגימים תפקידים שונים בבחינה. התנתקות נמצאת במעטפת הדף.','Me משתמשת במזהה מתוך Claims ולא במזהה שנמסר בכתובת. אין כאן API לקריאת פרופיל שרירותי של אדם אחר. זהות התפקיד בצילום היא נתון הרצה; את כללי ההרשאות עצמם יש להסביר לפי ה־Controller וה־middleware.'),
('13-error','מסך שגיאה מבוקר','Workspace/Error.cshtml','ApiFailure → WorkspaceController.OnActionExecutionAsync','לצורך צילום זה נפתחה כתובת תחנה שאינה קיימת. ה־API מחזיר 404 וה־View מציגה הודעה במקום ערכי אפס או עמוד שנראה תקין. זו הדגמה מכוונת של שגיאת קלט, לא קריסה של מסד הנתונים.','OnActionExecutionAsync מטפלת ב־ApiFailure שהוחזרה מפעולת המסך ומגדירה את קוד התשובה. שגיאה בזמן אימות מוקדם או כשל תשתית כללי עשויים לעבור במסלול middleware אחר. חשוב להבחין בין 404, 403 ו־503 במקום לכנות את כולם שגיאת כניסה.'),
('14-edit-user','עריכת משתמש קיים','Workspace/EditUser.cshtml','WorkspaceController.EditUser / SaveUser → UsersController.Update','במצב עריכה נטענים הפרטים הקיימים וה־id נשלח בשדה מוסתר. סיסמה ריקה פירושה שמירת הסיסמה הקיימת. מנהל יכול לשנות שם, דוא״ל, תפקיד ופעילות בכפוף להגנות על חשבונו ועל המנהל הפעיל האחרון.','Update משתמשת בעסקה ברמת Serializable, בודקת כפילות דוא״ל, מגדילה SessionVersion ושומרת. שדה מוסתר אינו מנגנון הרשאה; ה־API בודק את המשתמש ואת התפקיד. צילום הטופס נעשה בלי לשמור שינוי לחשבון המנהל.'),
('15-confirm','אישור פעולה','Workspace/Confirm.cshtml','WorkspaceController.Confirm → WorkspaceController.Apply','מסך האישור מציג סוג רשומה, מזהה וסטטוס יעד. Confirm change מבצע POST, בעוד Cancel חוזר לרשימה. לפני השלמת העברה מופיעה תזכורת שהפעולה הפיזית צריכה להיות גמורה. פתיחת דף האישור אינה מסיימת משימה.','kind, id ו־status נשלחים בטופס. Apply בוחרת נתיב API מוגדר, ולכן לא מאפשרת כתובת חופשית מהלקוח. בדיקות ה־API עדיין נדרשות: משתמש יכול לשנות שדות hidden. לצורך התיעוד נפתח מסך האישור בלבד, בלי לסמן העברה אמיתית כמבוצעת.'),
('16-rider','חיפוש אופניים לרוכב','Rider/Index.cshtml','RiderController.Index → RiderApiController.Stations','המסך מציג זמינות פשוטה לרוכב, עם חיפוש בשם תחנה, מועדפים וקישור לדיווח. זמני המקור והקבלה מופיעים כדי שהרוכב יוכל להעריך את המידע. אין כאן הזמנת אופניים או התחייבות שכלי יישאר בתחנה עד ההגעה.','ה־API מסתיר כמות נוכחית כאשר המדידה ישנה או שהשכרה סגורה. הוא מוסיף favorite לפי רשומות המשתמש המחובר בלבד. RiderController מבצעת סינון לתצוגה; התפריט מצומצם לאזור הרוכבים ומונע בלבול עם תפעול.'),
('17-favorites','תחנות מועדפות','Rider/Index.cshtml','RiderController.Favorite → RiderApiController.Favorite / RemoveFavorite','זהו מצב מסונן של מסך הרוכב ולא View נפרדת. סימון Favorites only מציג תחנות שסומנו על ידי החשבון. Add favorite ו־Remove favorite משנים את ההעדפה האישית ואינם משנים את מדידת התחנה או את העדפות המשתמשים האחרים.','המפתח המורכב UserId ו־StationId מונע אותה העדפה כפולה. Favorite בודקת שהתחנה קיימת לפני שמירה, ו־RemoveFavorite מוחקת רק את רשומת המשתמש הנוכחי. מועדף התיעוד הוסר לאחר הצילום. הנתונים האישיים אינם נכנסים למטמון התחנות המשותף.'),
('18-report','שליחת דיווח ומעקב אישי','Rider/Report.cshtml','RiderController.Report → RiderApiController.Report / Issues','כאשר מגיעים דרך תחנה, מופיע טופס תיאור התקלה עם מזהה התחנה. מתחת מוצגים הדיווחים האישיים והסטטוס שלהם. כניסה ל־My reports ללא תחנה מציגה היסטוריה בלי טופס יצירת דיווח לתחנה לא מוגדרת.','התיאור נדרש להיות באורך מתאים, והשרת בודק גם רווחים בלבד. לאחר הצלחה מוצגת הודעת אישור והדף נטען מחדש. בעת כשל מוצגת הודעה ורשימת הדיווחים נטענת מחדש. רוכב אינו יכול לבחור UserId של אדם אחר בגוף הבקשה.'),
('19-rider-profile','זהות רוכב והרשאותיו','Workspace/Profile.cshtml','WorkspaceController.Profile → AuthController.Me','אותו דף פרופיל משמש גם רוכב, עם תפריט המתאים לתפקיד RIDER. זה מדגים שימוש חוזר ב־View בלי לשכפל עמוד כמעט זהה. פרטי החשבון המצולם הם של משתמש תיעוד, שהושבת בסיום.','במסנן Workspace קיימת החרגה של Profile ו־Logout מהפניית רוכבים לאזור Rider. בלעדיה לא היה ניתן להשתמש בפעולות משותפות אלו. ההחרגה אינה מעניקה לרוכב גישה לדשבורד תפעולי, לניהול משתמשים או להשלמת משימות.'),
('20-operator','מבט עובד תפעול','Workspace/Stations.cshtml','WorkspaceController.Stations → FleetController.Stations','עובד רואה את התחנות ואת פעולות התפעול, אך אין לו קישור Team management. לצורך צילום זה נבחר חיפוש ממוקד כדי להציג רשימה קריאה. הרשאות OPERATOR נבדקות גם בשרת, ולכן היעדר קישור אינו ההגנה היחידה.','בצילום הראשון של דשבורד העובד התקבלה 503, ובוצעה קריאה נוספת למסך התחנות. אין להסתיר זאת בדוח האימות או להסיק שנבדקה יציבות ארוכת טווח. הצלחת מסך ספציפי מתועדת בנפרד מהוכחה שכל מסדי הנתונים וכל תרחישי הכתיבה זמינים תמיד.')]
for i,(image,title,file,flow,body,technical) in enumerate(screens,1):
 add(f'מסכים {i:02} | {title}',body+'\n'+technical+'\nמסלול הפעולה: '+flow+'.\nהצילום מציג את האזור העליון של הדף במערכת המקומית. בטבלאות ארוכות ממשיכים בגלילה; התמונה אינה מציגה את כל רשומות הרשת.', ['StationApi/Views/'+file],None,4,image=image)
add('36. תהליך שלם: מן הלחיצה לשמירה','''הדגמת Rebalancing היא דרך טובה לקשור בין שכבות הפרויקט. המשתמש בוחר Mark completed בכרטיס. קישור GET פותח Confirm בלבד; אין כתיבה במסלול זה. לחיצה על Confirm change שולחת POST עם kind, id, status ו־token.
WorkspaceController.Apply בוחרת את endpoint של ההמלצה ושולחת PATCH באמצעות FleetApiClient. ה־API מאמת cookie, תפקיד ו־CSRF. Update מוודאת שהמשימה קיימת, שהמצב המבוקש מותר ושהתחנות שייכות למקור. בקשה שמשנה משימה סגורה נדחית, בעוד בקשה חוזרת לאותו מצב מטופלת באופן עקבי.
אחרי עדכון הרשומה ומדידות המשימה, SaveChangesAsync שומרת את השינויים. רק לאחר מכן נפסל המטמון ומוחזרת הרשומה. שכבת ה־Views קוראת את status מהתשובה, מציגה הודעת הצלחה ומפנה ל־Recommendations עם המסנן המתאים והמזהה להדגשה.
אם API מחזיר כשל, אין redirect הצלחה. גם כאשר נשמר COMPLETED, StationAnalysis עדיין נגזר מהספק. כך ניתן להבחין בין כשל שמירה, רשימה מסוננת שלא מציגה את המשימה, ומשימה שהושלמה אך לא הביאה לשיפור נצפה.''', ['StationApi/Controllers/WorkspaceController.cs'],'var saved = await api.Send',14)
add('37. בדיקות עסקיות דטרמיניסטיות','''FleetTests היא תוכנית Console שמריצה assertions ומסיימת בכשל אם תנאי אינו מתקיים. Program בונה תחנות מלאכותיות עם זמן נתון ומפעילה את SmartFleetEngine. הנתונים המלאכותיים קיימים בבדיקות בלבד ואינם מוזרמים אל מאגרי הייצור.
נבדקים מחסור, עודף, תחנה מאוזנת, מידע חסר, זמן ישן או עתידי, קיבולת לא תקינה, מניעת המלצות לא אפשריות וחישוב מדדים. מבחני DurationText מכסים אפס, יחיד ורבים, שעה מדויקת, שעה עם שארית וערכים שאינם סופיים. בדיקות הרשמה מוודאות DataAnnotations וגיבוב סיסמה.
לאחר הניקוי עברו 66 בדיקות עסקיות בהרצה הרגילה. מספר זה אינו כולל את בדיקות המטמון, HTTP, Razor ו־Kafka שמופעלות בהמשך. האפשרות --gbfs מוסיפה בדיקה חיה מול המקור, ולכן מספר הבדיקות והנתונים יכולים להשתנות בין הפעלות.
יש להסביר לבוחן מה בדיוק נבדק: פונקציה טהורה מול fixture אינה בדיקת עומס, בדיקת UI אינה עסקה מול MySQL, ובניית solution אינה אימות התנהגות. הפרויקט משלב מספר סוגי ראיות במקום להציג מספר יחיד כהבטחת איכות מלאה.''', ['FleetTests/Program.cs'],'Check("Empty-time metric',13)
add('38. בדיקות מטמון, HTTP ו־Kafka','''CacheChecks מפעילה FleetDataService אמיתית עם תחליף Redis ומטעין נתונים מדומה. היא בודקת cache hit, TTL של 60 שניות, חישוב מחדש של טריות, הפרדת מקורות, fallback אחרי JSON פגום, פסילה עקב כתיבה, שינוי גרסת מעבד ונפילת Redis. גם מטמון תחנה בודדת נבדק.
HttpChecks משתמשת ב־HttpMessageHandler שמחזיר תגובות מתוכננות. היא בודקת ניסיון חוזר אחרי כשל זמני, feed ריק תקין, כשל שאינו הופך להצלחה וביטול. אלו מקרי גבול שניתן לבדוק בלי לחכות שספק אמיתי ייפול.
KafkaChecks משתמשת ב־DispatchProxy ל־IProducer. TaskCompletionSource מאפשרת להשאיר שליחות ממתינות ולוודא שאין flush מוקדם. נבדקים key, topic, token, התאמת JSON, כשל, ביטול ואצווה ריקה. הבנאי הפנימי של היצרן נועד להזרים תלות זו בלי broker אמיתי.
מבחנים אלה אינם מוכיחים חיבור רשת תקין ל־Redis או Kafka. הם מוודאים שהקוד מגיב נכון לחוזה של התלות. בדיקות אינטגרציה בסביבה פעילה משלימות אותם, אך לא הורצו מחדש באמצעות Docker כחלק מניקוי הקוד.''', ['FleetTests/KafkaChecks.cs'],'var sending =',16)
add('39. בדיקות Razor ותרחישי קצה','''WebChecks מפעילה שרת Kestrel מקומי שמרנדר את ה־Views האמיתיות, אך מחליפה את ה־API העסקי ב־fixture. נבדקות טעינת המסכים, היעדר script, token בטפסים, כמות לא ידועה לעומת אפס, זמני דיווח, רענון אוטומטי והשהייתו.
נבדקים גם דחיית API תפעולי לרוכב, דחיית ניהול משתמשים לעובד, ושינוי משימה שעובר דרך Apply ומציג את הסטטוס המעודכן. שגיאת שמירה מדומה צריכה להופיע ללא הודעת הצלחה. קישור ההרשמה נבדק בתוך חלונית הכניסה וההתנתקות נבדקת בראש התוכן.
לצורך ספר זה בוצעו גם כניסה דרך API וצילומים מהמערכת המקומית ב־8080. אלו ראיות נוספות לכך שהמסכים זמינים, אך לא בוצע ניסוי של העברת אופניים פיזית ולא סומנו משימות אמיתיות כהושלמו. חשבונות צילום נוצרו בהרשאה והושבתו.
צילום מסך אינו תחליף לבדיקה של שינוי לאורך זמן. בפרט, מצב הנתונים בצילום היה ישן, ודשבורד עובד החזיר פעם אחת 503. יש לתאר את אלה כממצאים, לא למחוק את האזהרות כדי להציג מערכת שנראית מושלמת.''', ['FleetTests/WebChecks.cs'],'foreach (var status in',15)
add('40. הפעלה, הגדרות וסודות','''הפעלה מקומית מלאה נעשית דרך docker compose up -d --build. Compose מגדיר broker, MySQL, MongoDB, Redis, processor, ingestion ו־api. הפורטים הציבוריים קשורים ל־127.0.0.1. אתר היישום זמין כברירת מחדל ב־8080, והכתובות בין הקונטיינרים משתמשות בשמות השירותים ברשת הפנימית.
.env מחזיק סיסמת MySQL ופרטי seed, ו־setup.ps1 יוצר ערכים מקומיים כשצריך. אין לפרסם קובץ זה. MYSQL_ROOT_PASSWORD אינו אמור להיכנס לצילום או לספר. משתני DataSource בקליטה וב־API צריכים להתאים, בעיקר התחילית והמקור.
Volumes שומרים את MySQL, MongoDB ומפתחות Data Protection. מחיקת volume עלולה למחוק מידע או לפסול cookies. עדכון קוד במחשב אינו מעדכן image שכבר רץ: נדרשת בנייה מחדש אצל המשתמש. הספר אינו מבצע שינוי ב־Docker כדי להשיג צילום יפה יותר.
לפני הגשה מומלץ לבדוק בריאות שירותים, קליטה טרייה, כניסת תפקידים ותרחיש כתיבה בטוח. smoke-test.ps1 יוצר משתמש בדיקה ודיווחים מסומנים, בודק הרשאות ומנקה באמצעות השבתה וסגירה. הוא אינו משלים העברה אמיתית.''')
add('41. ניקוי הקוד והחלטות תחזוקה','''הניקוי האחרון התמקד בקוד שאינו תורם להתנהגות. הוסרו שתי מחלקות ללא שימוש, מתודה שאינה נקראת, משתנים מיותרים והפניות לחבילות שלא שימשו את השירות. קוד שליחה חוזר בשלושת שירותי הקליטה הועבר ל־SendBatchAsync ביצרן הקיים.
קוד C# בייצור ירד מ־2,884 ל־2,716 שורות, ומ־58 ל־56 קבצים. הספירה כוללת שורות ריקות והערות, ואינה כוללת bin/obj, Razor או CSS. בדיקות נוספו בנפרד: חמישה קובצי בדיקות במקום ארבעה. לא נמחקו בדיקות כדי להציג צמצום גדול יותר.
ה־Controllers בעלי הנתיבים הקיימים נשמרו. גם migrations, חוזי JSON ושמות שדות אחסון נשארו. תיקון מוסכמות שמות אינו מצדיק שבירת מסד או לקוח חיצוני. camelCase מתאים למשתנים ולפרמטרים, PascalCase למחלקות ומתודות, ומיפוי מפורש נחוץ כאשר שם חיצוני שונה.
היעד ההנדסי הוא פחות כפילות ויותר הבנה. קובץ קצר בעל אחריות ברורה יכול להיות עדיף על מיזוג הכול לקובץ ארוך. מנגד, helper שלא משרת צורך אמיתי ניתן להסרה. ההחלטה מתקבלת לפי שימושים ותלות, לא לפי מספר קבצים בלבד.''', ['BikeFleetOperationPlatform/Services/KafkaProducerService.cs'],'public async Task SendBatchAsync',12)
add('42. מגבלות והמשך פיתוח','''המערכת היא בסיס תפעולי לימודי עם נתונים חיצוניים אמיתיים. היא אינה מערכת השכרה, ניווט משאיות או ניהול מנעולים. התחזיות ליניאריות, המרחק בהמלצות יחסי, ואין הוכחה מבוקרת שהמלצות משפרות זמינות בפועל. אלו גבולות שיש להסביר בגלוי בבחינה.
בצילום המערכת, המדידות שהיו זמינות במסד לא עמדו בסף הטריות. האתר הציג אזהרה במקום זמינות שגויה. כדי לאבחן סיבת תקלה יש לבדוק בנפרד מקור HTTP, שליחה ל־Kafka, צריכה ושמירה, אך עבודת התיעוד לא שינתה תשתית ולא הפעילה מחדש קונטיינרים.
להמשך אפשר לשקול pagination ברשימות, source health ייעודי, תור שגיאות, ניטור זמני קליטה ובדיקות אינטגרציה אוטומטיות. לתחזיות אפשר להוסיף תכונות זמן ומזג אוויר רק לאחר איסוף נתונים ובדיקת תועלת מול מודל הבסיס. לפריסה מרובת שרתים יש לתכנן תיאום כתיבות שאינו מסתמך על SemaphoreSlim מקומי.
הצעות אלו אינן חלק מהמימוש המתועד. הספר מבחין בין הקיים, הנבדק והעתידי כדי שהמגישים יוכלו להציג בביטחון את המערכת שבנו, בלי להתחייב ליכולות שאינן קיימות.''')
add('43. הכנה להצגה ולשאלות בבחינה','''הצגה מומלצת מתחילה בבעיה: תחנה ריקה או מלאה ופיזור לא מאוזן. לאחר מכן מציגים את תרשים הזרימה, מסך Overview, תחנה בודדת ומשימת העברה. מסבירים מראש שהנתונים תלויים בספק ושצילום בזמן מידע ישן ידגים את מנגנון האמינות במקום תחזית.
שאלה: למה יש גם MySQL וגם MongoDB? תשובה: ישויות תפעול ומטא־דאטה נשמרות יחסית, בעוד מצב והיסטוריית מדידות נשמרים כמסמכים; ה־API מאחד ביניהם. זו בחירת הפרויקט, לא טענה שאי אפשר לבנות פתרון עם מסד יחיד.
שאלה: למה צריך Kafka? תשובה: הפרדה בין קליטה לעיבוד, שמירת מיקום צריכה וחזרה על הודעות לאחר כשל. למה Redis? כדי להקטין חישוב חוזר, עם תוקף קצר ו־fallback. למה אין JavaScript? הממשק מרונדר בשרת ומשתמש בטפסים, הפניות ורענון HTML.
שאלה: למה משימה הושלמה ותחנה עדיין Warning? תשובה: מצב המשימה מתעד עבודה, ואילו סיכון התחנה נגזר מהמדידה. שאלה: האם MAE הוא אחוז דיוק? לא; זו שגיאה ממוצעת באופניים. כדאי לדעת להראות את הפונקציה הרלוונטית בקוד ולא להסתפק בשם הטכנולוגיה.''')
(OUT/'sections.json').write_text(json.dumps(sections,ensure_ascii=False,indent=2),encoding='utf-8');print('Total',len(sections))
